std::string json_escape(std::string_view value) {
    std::ostringstream out;
    for (char ch : value) {
        switch (ch) {
            case '\\':
                out << "\\\\";
                break;
            case '"':
                out << "\\\"";
                break;
            case '\n':
                out << "\\n";
                break;
            case '\r':
                out << "\\r";
                break;
            case '\t':
                out << "\\t";
                break;
            default:
                out << ch;
        }
    }
    return out.str();
}

class NativeFamilySha256 {
public:
    NativeFamilySha256()
        : state_{
              0x6a09e667u, 0xbb67ae85u, 0x3c6ef372u, 0xa54ff53au,
              0x510e527fu, 0x9b05688cu, 0x1f83d9abu, 0x5be0cd19u} {}

    void update(const std::uint8_t* data, std::size_t size) {
        total_bytes_ += static_cast<std::uint64_t>(size);
        while (size > 0) {
            const std::size_t available = block_.size() - block_size_;
            const std::size_t count = std::min(size, available);
            std::memcpy(block_.data() + block_size_, data, count);
            block_size_ += count;
            data += count;
            size -= count;
            if (block_size_ == block_.size()) {
                transform(block_.data());
                block_size_ = 0;
            }
        }
    }

    std::string finish_hex() {
        const std::uint64_t bit_length = total_bytes_ * 8u;
        block_[block_size_++] = 0x80u;
        if (block_size_ > 56) {
            std::fill(block_.begin() + static_cast<std::ptrdiff_t>(block_size_), block_.end(), 0u);
            transform(block_.data());
            block_size_ = 0;
        }
        std::fill(
            block_.begin() + static_cast<std::ptrdiff_t>(block_size_),
            block_.begin() + 56,
            0u);
        for (std::size_t i = 0; i < 8; ++i) {
            block_[63 - i] = static_cast<std::uint8_t>(bit_length >> (i * 8));
        }
        transform(block_.data());
        std::ostringstream out;
        out << std::hex << std::setfill('0');
        for (std::uint32_t word : state_) {
            out << std::setw(8) << word;
        }
        return out.str();
    }

private:
    static std::uint32_t rotate_right(std::uint32_t value, std::uint32_t amount) {
        return (value >> amount) | (value << (32u - amount));
    }

    void transform(const std::uint8_t* block) {
        static constexpr std::array<std::uint32_t, 64> kRoundConstants = {
            0x428a2f98u, 0x71374491u, 0xb5c0fbcfu, 0xe9b5dba5u,
            0x3956c25bu, 0x59f111f1u, 0x923f82a4u, 0xab1c5ed5u,
            0xd807aa98u, 0x12835b01u, 0x243185beu, 0x550c7dc3u,
            0x72be5d74u, 0x80deb1feu, 0x9bdc06a7u, 0xc19bf174u,
            0xe49b69c1u, 0xefbe4786u, 0x0fc19dc6u, 0x240ca1ccu,
            0x2de92c6fu, 0x4a7484aau, 0x5cb0a9dcu, 0x76f988dau,
            0x983e5152u, 0xa831c66du, 0xb00327c8u, 0xbf597fc7u,
            0xc6e00bf3u, 0xd5a79147u, 0x06ca6351u, 0x14292967u,
            0x27b70a85u, 0x2e1b2138u, 0x4d2c6dfcu, 0x53380d13u,
            0x650a7354u, 0x766a0abbu, 0x81c2c92eu, 0x92722c85u,
            0xa2bfe8a1u, 0xa81a664bu, 0xc24b8b70u, 0xc76c51a3u,
            0xd192e819u, 0xd6990624u, 0xf40e3585u, 0x106aa070u,
            0x19a4c116u, 0x1e376c08u, 0x2748774cu, 0x34b0bcb5u,
            0x391c0cb3u, 0x4ed8aa4au, 0x5b9cca4fu, 0x682e6ff3u,
            0x748f82eeu, 0x78a5636fu, 0x84c87814u, 0x8cc70208u,
            0x90befffau, 0xa4506cebu, 0xbef9a3f7u, 0xc67178f2u,
        };
        std::array<std::uint32_t, 64> schedule{};
        for (std::size_t i = 0; i < 16; ++i) {
            const std::size_t offset = i * 4;
            schedule[i] =
                (static_cast<std::uint32_t>(block[offset]) << 24u) |
                (static_cast<std::uint32_t>(block[offset + 1]) << 16u) |
                (static_cast<std::uint32_t>(block[offset + 2]) << 8u) |
                static_cast<std::uint32_t>(block[offset + 3]);
        }
        for (std::size_t i = 16; i < schedule.size(); ++i) {
            const std::uint32_t s0 = rotate_right(schedule[i - 15], 7u) ^
                rotate_right(schedule[i - 15], 18u) ^ (schedule[i - 15] >> 3u);
            const std::uint32_t s1 = rotate_right(schedule[i - 2], 17u) ^
                rotate_right(schedule[i - 2], 19u) ^ (schedule[i - 2] >> 10u);
            schedule[i] = schedule[i - 16] + s0 + schedule[i - 7] + s1;
        }

        std::uint32_t a = state_[0];
        std::uint32_t b = state_[1];
        std::uint32_t c = state_[2];
        std::uint32_t d = state_[3];
        std::uint32_t e = state_[4];
        std::uint32_t f = state_[5];
        std::uint32_t g = state_[6];
        std::uint32_t h = state_[7];
        for (std::size_t i = 0; i < schedule.size(); ++i) {
            const std::uint32_t sum1 = rotate_right(e, 6u) ^ rotate_right(e, 11u) ^ rotate_right(e, 25u);
            const std::uint32_t choose = (e & f) ^ ((~e) & g);
            const std::uint32_t temp1 = h + sum1 + choose + kRoundConstants[i] + schedule[i];
            const std::uint32_t sum0 = rotate_right(a, 2u) ^ rotate_right(a, 13u) ^ rotate_right(a, 22u);
            const std::uint32_t majority = (a & b) ^ (a & c) ^ (b & c);
            const std::uint32_t temp2 = sum0 + majority;
            h = g;
            g = f;
            f = e;
            e = d + temp1;
            d = c;
            c = b;
            b = a;
            a = temp1 + temp2;
        }
        state_[0] += a;
        state_[1] += b;
        state_[2] += c;
        state_[3] += d;
        state_[4] += e;
        state_[5] += f;
        state_[6] += g;
        state_[7] += h;
    }

    std::array<std::uint32_t, 8> state_{};
    std::array<std::uint8_t, 64> block_{};
    std::size_t block_size_ = 0;
    std::uint64_t total_bytes_ = 0;
};

bool native_family_sha256_file(
    const std::filesystem::path& path,
    std::string* sha256,
    std::int64_t* nbytes,
    std::string* error) {
    if (sha256 == nullptr || nbytes == nullptr || error == nullptr) {
        return false;
    }
    std::ifstream input(path, std::ios::binary);
    if (!input) {
        *error = "failed to open native family parameter sidecar for SHA-256";
        return false;
    }
    NativeFamilySha256 digest;
    std::array<char, 64 * 1024> chunk{};
    std::int64_t total = 0;
    while (input) {
        input.read(chunk.data(), static_cast<std::streamsize>(chunk.size()));
        const std::streamsize count = input.gcount();
        if (count < 0 || total > std::numeric_limits<std::int64_t>::max() - count) {
            *error = "native family parameter sidecar size overflow";
            return false;
        }
        if (count > 0) {
            digest.update(
                reinterpret_cast<const std::uint8_t*>(chunk.data()),
                static_cast<std::size_t>(count));
            total += count;
        }
    }
    if (!input.eof()) {
        *error = "failed while reading native family parameter sidecar for SHA-256";
        return false;
    }
    *sha256 = digest.finish_hex();
    *nbytes = total;
    return true;
}

std::string require_value(int argc, char** argv, int* index, const std::string& flag) {
    if (*index + 1 >= argc) {
        std::cerr << flag << " requires a value\n";
        std::exit(2);
    }
    *index += 1;
    return argv[*index];
}

std::int64_t parse_i64(const std::string& value, const std::string& flag) {
    try {
        std::size_t pos = 0;
        long long parsed = std::stoll(value, &pos, 10);
        if (pos != value.size()) {
            throw std::invalid_argument("trailing characters");
        }
        return static_cast<std::int64_t>(parsed);
    } catch (const std::exception&) {
        std::cerr << flag << " expects an integer, got '" << value << "'\n";
        std::exit(2);
    }
}

double parse_f64(const std::string& value, const std::string& flag) {
    try {
        std::size_t pos = 0;
        double parsed = std::stod(value, &pos);
        if (pos != value.size()) {
            throw std::invalid_argument("trailing characters");
        }
        return parsed;
    } catch (const std::exception&) {
        std::cerr << flag << " expects a number, got '" << value << "'\n";
        std::exit(2);
    }
}

std::string normalize_lr_schedule(std::string value) {
    for (char& ch : value) {
        if (ch == '_') {
            ch = '-';
        } else {
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
    }
    if (value == "fixed") {
        value = "constant";
    }
    if (value == "cosine-decay") {
        value = "cosine";
    }
    if (value != "constant" && value != "cosine") {
        std::cerr << "--lr-schedule must be cosine or constant\n";
        std::exit(2);
    }
    return value;
}

double scheduled_learning_rate(const Config& cfg, std::int64_t step) {
    const double base_lr = cfg.learning_rate > 0.0 ? cfg.learning_rate : 0.0;
    if (base_lr <= 0.0) {
        return 0.0;
    }
    const std::int64_t warmup_steps = std::max<std::int64_t>(0, cfg.warmup_steps);
    if (warmup_steps > 0 && step <= warmup_steps) {
        return base_lr * (static_cast<double>(std::max<std::int64_t>(1, step)) /
                          static_cast<double>(warmup_steps));
    }
    if (cfg.lr_schedule == "constant") {
        return base_lr;
    }
    const double floor_fraction = std::clamp(cfg.final_lr_fraction, 0.0, 1.0);
    const double floor_lr = base_lr * floor_fraction;
    const std::int64_t decay_steps = std::max<std::int64_t>(1, cfg.max_steps - warmup_steps);
    const double progress = std::clamp(
        static_cast<double>(std::max<std::int64_t>(0, step - warmup_steps)) /
            static_cast<double>(decay_steps),
        0.0,
        1.0);
    constexpr double kPi = 3.14159265358979323846264338327950288;
    const double cosine = 0.5 * (1.0 + std::cos(kPi * progress));
    return floor_lr + (base_lr - floor_lr) * cosine;
}

Config with_scheduled_learning_rate(Config cfg, std::int64_t step) {
    cfg.learning_rate = scheduled_learning_rate(cfg, step);
    return cfg;
}

neuralfn::native_train::FamilyOptimizerHyperparameters native_family_optimizer_hyperparameters(
    const Config& cfg,
    std::int64_t optimizer_step) {
    neuralfn::native_train::FamilyOptimizerHyperparameters hyper;
    const std::int64_t absolute_optimizer_step = std::max<std::int64_t>(1, optimizer_step);
    hyper.learning_rate = static_cast<float>(
        neuralfn::native_train::family_scheduled_learning_rate(
            cfg.learning_rate,
            absolute_optimizer_step,
            cfg.max_steps,
            cfg.warmup_steps,
            cfg.lr_schedule,
            cfg.final_lr_fraction));
    hyper.bias_correction1 = 1.0f - std::pow(hyper.beta1, static_cast<float>(absolute_optimizer_step));
    hyper.sqrt_bias_correction2 = std::sqrt(
        1.0f - std::pow(hyper.beta2, static_cast<float>(absolute_optimizer_step)));
    return hyper;
}

std::vector<std::string> split_csv(std::string_view value) {
    std::vector<std::string> out;
    std::string current;
    for (char ch : value) {
        if (ch == ',') {
            if (!current.empty()) {
                out.push_back(current);
            }
            current.clear();
        } else if (!std::isspace(static_cast<unsigned char>(ch))) {
            current.push_back(ch);
        }
    }
    if (!current.empty()) {
        out.push_back(current);
    }
    return out;
}

bool env_flag_enabled_or_default(const char* name, bool default_value) {
    const char* raw = std::getenv(name);
    if (raw == nullptr || raw[0] == '\0') {
        return default_value;
    }
    std::string value(raw);
    std::transform(value.begin(), value.end(), value.begin(), [](unsigned char ch) {
        return static_cast<char>(std::tolower(ch));
    });
    return value == "1" || value == "true" || value == "yes" || value == "on";
}

bool native_family_cuda_graph_capture_enabled() {
    return env_flag_enabled_or_default(
        "NFN_NATIVE_FAMILY_PRODUCTION_CUDA_GRAPH",
        NFN_NATIVE_PRODUCTION_LOOP != 0);
}

bool native_family_production_step_checksum_enabled() {
    return env_flag_enabled_or_default(
        "NFN_NATIVE_FAMILY_PRODUCTION_STEP_CHECKSUM",
        false);
}

bool native_family_temporary_replay_validation_enabled() {
    return env_flag_enabled_or_default(
        "NFN_NATIVE_FAMILY_TEMPORARY_REPLAY_VALIDATE",
        false);
}

std::vector<std::string> family_production_missing_requirements() {
    if (NFN_NATIVE_PRODUCTION_LOOP != 0 && native_full_family_geometry_build_enabled()) {
        return {};
    }
    std::vector<std::string> missing = split_csv(NFN_NATIVE_MISSING_REQUIREMENTS);
    if (missing.empty()) {
        missing.push_back("production-family-forward-backward-optimizer-loop");
    }
    return missing;
}

std::vector<std::string> family_production_completed_requirements() {
    std::vector<std::string> completed = split_csv(NFN_NATIVE_COMPLETED_REQUIREMENTS);
    if (NFN_NATIVE_PRODUCTION_LOOP != 0 && native_full_family_geometry_build_enabled() &&
        std::find(
            completed.begin(),
            completed.end(),
            "optimizer-updated-full-architecture-parameter-persistence") == completed.end()) {
        completed.push_back("optimizer-updated-full-architecture-parameter-persistence");
    }
    return completed;
}

const char* family_dataset_trainer_loop_status() {
    return NFN_NATIVE_PRODUCTION_LOOP != 0 && native_full_family_geometry_build_enabled()
        ? "native-loop-covered"
        : "native-family-dataset-loop-diagnostic";
}

const char* family_production_training_loop_json() {
    return NFN_NATIVE_PRODUCTION_LOOP != 0 && native_full_family_geometry_build_enabled()
        ? "true"
        : "false";
}

void write_json_string_array(std::ostream& out, const std::vector<std::string>& values, std::string_view indent) {
    for (std::size_t i = 0; i < values.size(); ++i) {
        out << indent << "\"" << json_escape(values[i]) << "\"";
        if (i + 1 != values.size()) {
            out << ",";
        }
        out << "\n";
    }
}

std::string json_string_array_inline(const std::vector<std::string>& values) {
    std::ostringstream out;
    out << "[";
    for (std::size_t i = 0; i < values.size(); ++i) {
        if (i != 0) {
            out << ",";
        }
        out << "\"" << json_escape(values[i]) << "\"";
    }
    out << "]";
    return out.str();
}

bool is_semantic_family(std::string_view family) {
    return family.find("semantic") != std::string_view::npos;
}

std::string normalized_id(std::string value) {
    for (char& ch : value) {
        if (ch == '_') {
            ch = '-';
        } else {
            ch = static_cast<char>(std::tolower(static_cast<unsigned char>(ch)));
        }
    }
    return value;
}

bool native_family_has_specialty_capture_host_control(std::string_view family_name) {
    (void)family_name;
    return false;
}

