bool native_family_jepa_target_backbone_exact_parity(std::string_view family_name) {
    const std::string family = normalized_id(std::string(family_name));
    return family.find("jepa") != std::string::npos ||
           family == "semantic-router-moe" ||
           family == "semantic-moe-jepa-evo" ||
           family == "diff-semantic-moe-jepa-evo";
}

bool is_semantic_moe_template(const Config& cfg) {
    const std::string family = normalized_id(NFN_NATIVE_MODEL_FAMILY);
    const std::string templ = normalized_id(cfg.template_name);
    return family == "semantic-moe-jepa-evo" ||
           family == "diff-semantic-moe-jepa-evo" ||
           templ == "semantic-moe-jepa-evo" ||
           templ == "semantic-moe-jepa-evo-modern" ||
           templ == "diff-semantic-moe-jepa-evo";
}

bool uses_semantic_expert_contract(const Config& cfg) {
    const std::string family = normalized_id(NFN_NATIVE_MODEL_FAMILY);
    const std::string templ = normalized_id(cfg.template_name);
    return family.find("semantic") != std::string::npos ||
           templ.find("semantic") != std::string::npos;
}

std::int64_t semantic_total_experts(const Config& cfg) {
    return cfg.semantic_shared_experts + cfg.semantic_vocab_dims + cfg.semantic_free_experts;
}

bool native_family_uses_auxfree_moe_balance(const std::string& family);
bool native_family_uses_standard_moe_router_aux_loss(const Config& cfg);

void apply_semantic_architecture_defaults(Config& cfg) {
    const bool semantic_moe = is_semantic_moe_template(cfg);
    const bool semantic_contract = uses_semantic_expert_contract(cfg);
    if (cfg.semantic_shared_experts < 0) {
        cfg.semantic_shared_experts = semantic_moe ? 2 : 0;
    }
    if (cfg.semantic_free_experts < 0) {
        cfg.semantic_free_experts = semantic_moe ? 8 : 0;
    }
    if (cfg.experts < 0) {
        cfg.experts = semantic_contract ? semantic_total_experts(cfg) : 8;
    }
    if (!cfg.router_aux_loss_coef_explicit) {
        const std::string family = normalized_id(NFN_NATIVE_MODEL_FAMILY);
        const std::string preset = normalized_id(cfg.template_name);
        const std::string full_identity = normalized_id(
            std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
        const bool legacy_standard_moe =
            !native_family_uses_auxfree_moe_balance(full_identity) &&
            (family == "mixllama" || family == "moe-jepa-evo" ||
             preset == "mixllama" || preset == "moe" ||
             preset == "mixllama-fast" || preset == "mixllama-fast-megakernel" ||
             preset == "moe-jepa-evo");
        cfg.router_aux_loss_coef = legacy_standard_moe ? 0.01 : 0.0;
    }
}

void validate_semantic_architecture(const Config& cfg) {
    if (cfg.num_layers <= 0) {
        std::cerr << "--num-layers must be at least 1\n";
        std::exit(2);
    }
    if (cfg.model_dim <= 0) {
        std::cerr << "--model-dim must be at least 1\n";
        std::exit(2);
    }
    if (cfg.hidden_dim == 0 || cfg.hidden_dim < -1) {
        std::cerr << "--hidden-dim must be at least 1 when provided\n";
        std::exit(2);
    }
    if (!(cfg.mlp_multiplier > 0.0) && cfg.mlp_multiplier != -1.0) {
        std::cerr << "--mlp-multiplier must be positive when provided\n";
        std::exit(2);
    }
    if (cfg.multiple_of < -1) {
        std::cerr << "--multiple-of must be non-negative when provided\n";
        std::exit(2);
    }
    if (cfg.ttt_hidden_dim <= 0) {
        std::cerr << "--ttt-hidden-dim must be at least 1\n";
        std::exit(2);
    }
    if (cfg.num_heads <= 0 || cfg.num_kv_heads <= 0 || cfg.num_heads % cfg.num_kv_heads != 0) {
        std::cerr << "--num-heads and --num-kv-heads must be positive and divisible\n";
        std::exit(2);
    }
    if (!(cfg.rope_theta > 0.0) || !std::isfinite(cfg.rope_theta)) {
        std::cerr << "--rope-theta must be finite and positive\n";
        std::exit(2);
    }
    if (cfg.rope_scaling_factor < 0.0 || !std::isfinite(cfg.rope_scaling_factor)) {
        std::cerr << "--rope-factor must be finite and non-negative\n";
        std::exit(2);
    }
    if (cfg.rope_original_max_position <= 0) {
        std::cerr << "--original-max-position must be positive\n";
        std::exit(2);
    }
    if (!std::isfinite(cfg.differential_lambda)) {
        std::cerr << "--diff-lambda must be finite\n";
        std::exit(2);
    }
    if (cfg.max_recurrence_steps <= 0) {
        std::cerr << "--max-recurrence-steps must be at least 1\n";
        std::exit(2);
    }
    if (cfg.halt_epsilon < 0.0 || !std::isfinite(cfg.halt_epsilon)) {
        std::cerr << "--halt-epsilon must be finite and non-negative\n";
        std::exit(2);
    }
    if (cfg.model_dim % cfg.num_heads != 0 || (cfg.model_dim / cfg.num_heads) % 2 != 0) {
        std::cerr << "--model-dim must provide an even head dimension for --num-heads\n";
        std::exit(2);
    }
    if (cfg.byte_patch_size <= 0 || cfg.byte_patch_stride < 0) {
        std::cerr << "--byte-patch-size must be at least 1 and --byte-patch-stride cannot be negative\n";
        std::exit(2);
    }
    if (cfg.vocab_size == 0 || cfg.vocab_size < -1) {
        std::cerr << "--vocab-size must be at least 1 when provided\n";
        std::exit(2);
    }
    if (cfg.padded_vocab_size == 0 || cfg.padded_vocab_size < -1) {
        std::cerr << "--padded-vocab-size must be at least 1 when provided\n";
        std::exit(2);
    }
    if (cfg.vocab_size > 0 && cfg.padded_vocab_size > 0 && cfg.padded_vocab_size < cfg.vocab_size) {
        std::cerr << "--padded-vocab-size cannot be smaller than --vocab-size\n";
        std::exit(2);
    }
    if (!cfg.graph_fingerprint.empty()) {
        const bool valid_graph_fingerprint = cfg.graph_fingerprint.size() == 64 &&
            std::all_of(
                cfg.graph_fingerprint.begin(),
                cfg.graph_fingerprint.end(),
                [](unsigned char ch) {
                    return (ch >= '0' && ch <= '9') || (ch >= 'a' && ch <= 'f');
                });
        if (!valid_graph_fingerprint) {
            std::cerr << "--graph-fingerprint must be one lowercase SHA-256 digest\n";
            std::exit(2);
        }
    }
    if (cfg.graph_file.empty() != cfg.graph_fingerprint.empty()) {
        std::cerr << "--graph-file and --graph-fingerprint must be supplied together\n";
        std::exit(2);
    }
    if (cfg.weight_decay < 0.0 || !std::isfinite(cfg.weight_decay)) {
        std::cerr << "--weight-decay must be finite and non-negative\n";
        std::exit(2);
    }
    if (cfg.router_aux_loss_coef < 0.0 || !std::isfinite(cfg.router_aux_loss_coef)) {
        std::cerr << "--router-aux-loss-coef must be finite and non-negative\n";
        std::exit(2);
    }
    const float router_aux_loss_coef_f32 =
        static_cast<float>(cfg.router_aux_loss_coef);
    if (!std::isfinite(router_aux_loss_coef_f32) ||
        (cfg.router_aux_loss_coef > 0.0 && router_aux_loss_coef_f32 == 0.0f)) {
        std::cerr
            << "--router-aux-loss-coef must be representable as a nonzero finite float32 when positive\n";
        std::exit(2);
    }
    if (cfg.router_aux_loss_coef > 0.0 &&
        !native_family_uses_standard_moe_router_aux_loss(cfg)) {
        std::cerr
            << "--router-aux-loss-coef is only supported by standard softmax-MoE native profiles\n";
        std::exit(2);
    }
    if (!cfg.graph_file.empty() && !cfg.unparsed_args.empty()) {
        std::cerr << "graph-authored native training rejects unrecognized arguments:";
        for (const std::string& arg : cfg.unparsed_args) {
            std::cerr << " " << arg;
        }
        std::cerr << "\n";
        std::exit(2);
    }
    if (cfg.semantic_vocab_dims <= 0) {
        std::cerr << "--semantic-vocab-dims must be at least 1\n";
        std::exit(2);
    }
    if (cfg.semantic_shared_experts < 0) {
        std::cerr << "--semantic-shared-experts must be non-negative\n";
        std::exit(2);
    }
    if (cfg.semantic_free_experts < 0) {
        std::cerr << "--semantic-free-experts must be non-negative\n";
        std::exit(2);
    }
    if (cfg.layers_per_expert <= 0) {
        std::cerr << "--layers-per-expert must be at least 1\n";
        std::exit(2);
    }
    if (cfg.top_k <= 0) {
        std::cerr << "--top-k must be at least 1\n";
        std::exit(2);
    }
    if (cfg.route_chunk_size <= 0) {
        std::cerr << "--route-chunk-size must be at least 1\n";
        std::exit(2);
    }
    if (cfg.jepa_mask_ratio < 0.0 || cfg.jepa_mask_ratio > 1.0 || !std::isfinite(cfg.jepa_mask_ratio)) {
        std::cerr << "--jepa-mask-ratio must be finite and between 0 and 1\n";
        std::exit(2);
    }
    if (cfg.jepa_mask_strategy != "random" && cfg.jepa_mask_strategy != "block") {
        std::cerr << "--jepa-mask-strategy must be random or block\n";
        std::exit(2);
    }
    if (cfg.evo_layer_interval <= 0) {
        std::cerr << "--evo-layer-interval must be at least 1\n";
        std::exit(2);
    }
    if (cfg.evo_layer_mutation_scale < 0.0) {
        std::cerr << "--evo-layer-mutation-scale must be non-negative\n";
        std::exit(2);
    }
    if (cfg.experts <= 0) {
        std::cerr << "--experts must be at least 1\n";
        std::exit(2);
    }
    if (uses_semantic_expert_contract(cfg)) {
        const std::int64_t expected = semantic_total_experts(cfg);
        if (cfg.experts != expected) {
            std::cerr << "--experts must equal semantic_shared_experts + semantic_vocab_dims + "
                         "semantic_free_experts ("
                      << expected << "), got " << cfg.experts << "\n";
            std::exit(2);
        }
    }
    if (cfg.top_k > cfg.experts) {
        std::cerr << "--top-k cannot exceed --experts\n";
        std::exit(2);
    }
    if (cfg.checkpoint_every_steps < 0) {
        std::cerr << "--checkpoint-every-steps must be non-negative\n";
        std::exit(2);
    }
}

