std::int64_t clamp_positive(std::int64_t value, std::int64_t fallback) {
    return value > 0 ? value : fallback;
}

std::int64_t family_default_vocab_size(const Config& cfg) {
    const std::string family =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    return family.find("hnet") != std::string::npos ? 256 : 50257;
}

std::int64_t family_default_padded_vocab_size(const Config& cfg) {
    const std::string family =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    return family.find("hnet") != std::string::npos ? 256 : 50304;
}

std::int64_t family_model_dim(const Config& cfg) {
    return clamp_positive(cfg.model_dim, 768);
}

bool family_uses_llama_mlp_defaults(const Config& cfg) {
    const std::string family = normalized_id(NFN_NATIVE_MODEL_FAMILY);
    const std::string templ = normalized_id(cfg.template_name);
    return family == "llama" || family == "mixllama" || family == "deepseek-v4" ||
           family == "moe-jepa-evo" || family == "semantic-router-moe" ||
           family == "jepa" || family == "semantic-dense-jepa" || family == "jamba" ||
           family == "seq2seq" || family == "diffusion" || family == "ttt-llama" ||
           family == "universal-llama" || family == "hnet-lm" ||
           templ == "llama" || templ == "mixllama" || templ == "jamba" ||
           templ == "seq2seq" || templ == "diffusion" || templ == "ttt-llama" ||
           templ == "universal-llama" || templ == "hnet-lm";
}

double family_mlp_multiplier(const Config& cfg) {
    if (cfg.mlp_multiplier > 0.0) {
        return cfg.mlp_multiplier;
    }
    return family_uses_llama_mlp_defaults(cfg) ? (8.0 / 3.0) : 4.0;
}

std::int64_t family_multiple_of(const Config& cfg) {
    if (cfg.multiple_of >= 0) {
        return cfg.multiple_of;
    }
    return family_uses_llama_mlp_defaults(cfg) ? 256 : 0;
}

std::int64_t family_hidden_dim(const Config& cfg) {
    if (cfg.hidden_dim > 0) {
        return cfg.hidden_dim;
    }
    const std::int64_t model_dim = family_model_dim(cfg);
    const std::int64_t multiple = family_multiple_of(cfg);
    std::int64_t hidden = static_cast<std::int64_t>(
        static_cast<double>(model_dim) * family_mlp_multiplier(cfg));
    hidden = std::max<std::int64_t>(hidden, 1);
    if (multiple > 0) {
        hidden = multiple * ((hidden + multiple - 1) / multiple);
    }
    return hidden;
}

std::int64_t family_ttt_hidden_dim(const Config& cfg) {
    return clamp_positive(cfg.ttt_hidden_dim, 32);
}

std::int64_t family_num_heads(const Config& cfg) {
    return clamp_positive(cfg.num_heads, 4);
}

std::int64_t family_num_kv_heads(const Config& cfg) {
    return clamp_positive(cfg.num_kv_heads, family_num_heads(cfg));
}

bool family_uses_kv_pca(const Config& cfg) {
    const std::string preset = normalized_id(cfg.template_name);
    return preset == "kv-pca-llama" || preset == "kv-pca-llama-modern";
}

bool family_uses_mla(const Config& cfg) {
    const std::string preset = normalized_id(cfg.template_name);
    return preset == "deepseek-v3" || preset == "deepseek-v3-modern";
}

std::int64_t family_reported_kv_pca_compressed_dim(const Config& cfg);
std::int64_t family_reported_mla_kv_lora_rank(const Config& cfg);
std::int64_t family_reported_mla_rope_dim(const Config& cfg);

bool family_uses_megakernel(const Config& cfg) {
    const std::string preset = normalized_id(cfg.template_name);
    return preset == "llama-fast-megakernel" || preset == "llama-megakernel" ||
        preset == "mixllama-fast-megakernel" ||
        preset == "semantic-router-moe-megakernel" ||
        preset == "jepa-semantic-hybrid-megakernel";
}

bool family_uses_sqrt_softplus_router(const Config& cfg) {
    return normalized_id(cfg.template_name) == "deepseek-v4";
}

std::int64_t family_mla_rope_dim(const Config& cfg) {
    const std::int64_t head_dim = family_model_dim(cfg) /
        std::max<std::int64_t>(1, family_num_heads(cfg));
    std::int64_t rope_dim = std::max<std::int64_t>(head_dim / 2, 2);
    if ((rope_dim & 1) != 0) {
        --rope_dim;
    }
    return std::clamp<std::int64_t>(rope_dim, 2, std::max<std::int64_t>(2, head_dim - 2));
}

std::int64_t family_mla_kv_lora_rank(const Config& cfg) {
    const std::int64_t head_dim = family_model_dim(cfg) /
        std::max<std::int64_t>(1, family_num_heads(cfg));
    return std::max<std::int64_t>(2 * head_dim, family_model_dim(cfg) / 2);
}

std::int64_t family_kv_pca_compressed_dim(const Config& cfg) {
    const std::int64_t heads = family_num_heads(cfg);
    const std::int64_t head_dim = family_model_dim(cfg) / std::max<std::int64_t>(1, heads);
    return std::max<std::int64_t>(1, head_dim / 4);
}

std::int64_t family_reported_kv_pca_compressed_dim(const Config& cfg) {
    return family_uses_kv_pca(cfg) ? family_kv_pca_compressed_dim(cfg) : 0;
}

std::int64_t family_reported_mla_kv_lora_rank(const Config& cfg) {
    return family_uses_mla(cfg) ? family_mla_kv_lora_rank(cfg) : 0;
}

std::int64_t family_reported_mla_rope_dim(const Config& cfg) {
    return family_uses_mla(cfg) ? family_mla_rope_dim(cfg) : 0;
}

struct FamilyAttentionGeometry {
    bool use_sparse_rules = false;
    std::int64_t window = 0;
    std::int64_t num_sinks = 0;
    std::int64_t block_size = 0;
    std::int64_t compress_stride = 0;
};

FamilyAttentionGeometry family_attention_geometry(const Config& cfg) {
    const std::string preset = normalized_id(cfg.template_name);
    FamilyAttentionGeometry geometry;
    if (preset == "gemma3") {
        geometry.use_sparse_rules = true;
        geometry.window = 256;
    } else if (preset == "longctx-sparse-llama") {
        geometry.use_sparse_rules = true;
        geometry.window = 128;
        geometry.num_sinks = 4;
        geometry.block_size = 64;
        geometry.compress_stride = 16;
    } else if (preset == "qwen3-longctx") {
        geometry.use_sparse_rules = true;
        geometry.window = 256;
        geometry.num_sinks = 4;
    } else if (preset == "deepseek-v4" || preset == "diff-semantic-moe-jepa-evo") {
        geometry.use_sparse_rules = true;
        geometry.window = 128;
        geometry.num_sinks = 4;
        geometry.block_size = 64;
        geometry.compress_stride = 16;
    }
    return geometry;
}

bool family_uses_qk_norm(const Config& cfg) {
    const std::string preset = normalized_id(cfg.template_name);
    return preset == "deepseek-v3" || preset == "deepseek-v4" ||
        preset == "gemma3" || preset == "diff-semantic-moe-jepa-evo";
}

double family_rope_scaling_factor(const Config& cfg) {
    if (cfg.rope_scaling_factor > 0.0) {
        return cfg.rope_scaling_factor;
    }
    return normalized_id(cfg.template_name) == "qwen3-longctx" ? 4.0 : 1.0;
}

std::int64_t family_rope_original_max_position(const Config& cfg) {
    return cfg.rope_original_max_position > 0 ? cfg.rope_original_max_position : 2048;
}

float family_rope_inverse_frequency(const Config& cfg, std::int64_t head_dim, std::int64_t index) {
    const float base_frequency = 1.0f / std::pow(
        static_cast<float>(cfg.rope_theta),
        static_cast<float>(2 * index) / static_cast<float>(head_dim));
    const double factor = family_rope_scaling_factor(cfg);
    if (factor <= 1.0 || normalized_id(cfg.template_name) != "qwen3-longctx") {
        return base_frequency;
    }
    constexpr double kTwoPi = 6.28318530717958647692;
    constexpr double kBetaFast = 32.0;
    constexpr double kBetaSlow = 1.0;
    const double dim = static_cast<double>(head_dim);
    const double base = cfg.rope_theta;
    const double original = static_cast<double>(family_rope_original_max_position(cfg));
    const auto correction_dim = [&](double rotations) {
        return dim * std::log(original / (rotations * kTwoPi)) / (2.0 * std::log(base));
    };
    const std::int64_t max_index = std::max<std::int64_t>(0, head_dim / 2 - 1);
    const std::int64_t low = std::clamp<std::int64_t>(
        static_cast<std::int64_t>(std::floor(correction_dim(kBetaFast))), 0, max_index);
    const std::int64_t high = std::clamp<std::int64_t>(
        static_cast<std::int64_t>(std::ceil(correction_dim(kBetaSlow))), 0, max_index);
    if (high <= low) {
        return index <= low ? base_frequency : base_frequency / static_cast<float>(factor);
    }
    const float ramp = std::clamp(
        static_cast<float>(index - low) / static_cast<float>(high - low), 0.0f, 1.0f);
    return base_frequency * ((1.0f - ramp) + ramp / static_cast<float>(factor));
}

constexpr std::int64_t kNativeSemanticHashTables = 8;
constexpr std::int64_t kNativeSemanticHashPlanes = 12;
constexpr std::int64_t kNativeSemanticHashBuckets = 1LL << 12;
constexpr std::int64_t kNativeSemanticCanonicalDims = 86;
constexpr std::int64_t kNativeSemanticProjectorSemanticDims = kNativeSemanticCanonicalDims + 1;
constexpr std::int64_t kNativeSemanticCanonicalMaxTerms = 5959;
constexpr std::int64_t kNativeSemanticCanonicalTotalTerms = 12698;
constexpr std::int64_t kNativeSemanticProjectorResidualDims = 64;
constexpr std::int64_t kNativeSemanticPredictorHiddenDims = 43;
constexpr std::array<std::int64_t, kNativeSemanticCanonicalDims> kNativeSemanticCanonicalTermCounts = {
    566, 535, 427, 215, 456, 240, 235, 247, 126, 91, 64, 100, 65, 48, 49, 68,
    66, 46, 47, 20, 41, 22, 26, 45, 40, 64, 43, 61, 86, 74, 47, 28, 99, 42,
    21, 31, 99, 73, 62, 33, 24, 22, 43, 26, 47, 35, 31, 33, 38, 34, 46, 38,
    50, 84, 45, 195, 57, 31, 44, 38, 21, 28, 32, 43, 37, 25, 23, 56, 42, 70,
    54, 43, 68, 49, 20, 25, 21, 14, 34, 28, 28, 49, 110, 49, 61, 5959,
};

bool native_family_semantic_per_term_topic_head_supported(std::int64_t semantic_dims) {
    return semantic_dims == kNativeSemanticCanonicalDims;
}

std::vector<std::int64_t> native_family_semantic_canonical_term_offsets() {
    std::vector<std::int64_t> offsets;
    offsets.reserve(kNativeSemanticCanonicalTermCounts.size());
    std::int64_t offset = 0;
    for (std::int64_t count : kNativeSemanticCanonicalTermCounts) {
        offsets.push_back(offset);
        offset += count;
    }
    return offsets;
}

std::int64_t family_byte_patch_size(const Config& cfg) {
    return clamp_positive(cfg.byte_patch_size, 4);
}

std::int64_t family_byte_patch_stride(const Config& cfg) {
    return cfg.byte_patch_stride > 0 ? cfg.byte_patch_stride : family_byte_patch_size(cfg);
}

std::int64_t family_vocab_size(const Config& cfg) {
    return clamp_positive(cfg.vocab_size, family_default_vocab_size(cfg));
}

std::int64_t family_padded_vocab_size(const Config& cfg) {
    return std::max<std::int64_t>(
        family_vocab_size(cfg),
        clamp_positive(cfg.padded_vocab_size, family_default_padded_vocab_size(cfg)));
}

bool native_family_uses_auxfree_moe_balance(const std::string& family) {
    return family.find("auxfree") != std::string::npos ||
        family.find("deepseek-v3") != std::string::npos ||
        family.find("deepseek-v4") != std::string::npos ||
        (family.find("modern") != std::string::npos &&
         (family.find("moe") != std::string::npos ||
          family.find("mixllama") != std::string::npos ||
          family.find("deepseek") != std::string::npos));
}

bool native_family_uses_standard_moe_router_aux_loss(const Config& cfg) {
    const std::string family = normalized_id(NFN_NATIVE_MODEL_FAMILY);
    const std::string full_identity =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    return !native_family_uses_auxfree_moe_balance(full_identity) &&
        (family == "mixllama" || family == "moe-jepa-evo" || family == "jamba");
}

std::vector<ParameterBufferSpec> family_parameter_buffers(const Config& cfg) {
    const std::string family =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    const std::int64_t vocab = family_padded_vocab_size(cfg);
    const std::int64_t model_dim = family_model_dim(cfg);
    const std::int64_t hidden_dim = family_hidden_dim(cfg);
    const std::int64_t layers = clamp_positive(cfg.num_layers, 1);
    const std::int64_t experts = clamp_positive(cfg.experts, 8);
    const std::int64_t top_k = clamp_positive(cfg.top_k, 1);
    const std::int64_t layers_per_expert = clamp_positive(cfg.layers_per_expert, 1);
    const std::int64_t expert_layer_copies = experts * layers_per_expert;
    const std::int64_t semantic_vocab_dims = clamp_positive(cfg.semantic_vocab_dims, 86);
    const std::int64_t semantic_shared_experts = std::max<std::int64_t>(0, cfg.semantic_shared_experts);
    const std::int64_t semantic_free_experts = std::max<std::int64_t>(0, cfg.semantic_free_experts);
    const std::int64_t semantic_route_dims =
        native_family_semantic_per_term_topic_head_supported(semantic_vocab_dims)
            ? kNativeSemanticProjectorSemanticDims
            : semantic_vocab_dims;
    const std::int64_t heads = family_num_heads(cfg);
    const std::int64_t kv_heads = family_uses_mla(cfg) ? heads : family_num_kv_heads(cfg);
    const std::int64_t head_dim = model_dim / heads;
    const std::int64_t kv_dim = kv_heads * head_dim;
    const bool kv_pca_mode = family_uses_kv_pca(cfg);
    const std::int64_t kv_pca_dim = family_kv_pca_compressed_dim(cfg);
    const bool mla_mode = family_uses_mla(cfg);
    const std::int64_t mla_rope_dim = family_mla_rope_dim(cfg);
    const std::int64_t mla_nope_dim = head_dim - mla_rope_dim;
    const std::int64_t mla_kv_lora_rank = family_mla_kv_lora_rank(cfg);
    // Hidden-backbone specialty families reuse the full dense attention/FFN
    // composition. Seq2seq retains its legacy packed-QKV contract because its
    // dedicated encoder/decoder step consumes that layout directly.
    const bool split_attention_layout =
        (native_full_family_geometry_build_enabled() && !native_seq2seq_graph_build_enabled()) ||
        (native_full_specialized_geometry_build_enabled() &&
         !native_seq2seq_graph_build_enabled() &&
         !native_hnet_graph_build_enabled());
    const bool per_layer_moe_layout = native_full_moe_geometry_build_enabled();
    std::vector<ParameterBufferSpec> buffers = {
        // Byte-HNet consumes byte_patch_embed rather than the generic token
        // embedding node, so retain this ABI slot for vocab/layout discovery
        // without presenting it as an optimizer-owned parameter.
        {"token_embedding.weight", vocab * model_dim, family.find("hnet") == std::string::npos},
        {"final_norm.weight", model_dim, true},
        {"lm_head.weight", vocab * model_dim, family.find("diffusion") == std::string::npos},
    };
    for (std::int64_t layer = 0; layer < layers; ++layer) {
        const std::string prefix = "layers." + std::to_string(layer) + ".";
        buffers.push_back({prefix + "attention_norm.weight", model_dim, true});
        if (mla_mode) {
            buffers.push_back({prefix + "q_proj.weight", model_dim * model_dim, true});
            buffers.push_back({prefix + "kv_a.weight", (mla_kv_lora_rank + mla_rope_dim) * model_dim, true});
            buffers.push_back({prefix + "kv_b.weight",
                               heads * (mla_nope_dim + head_dim) * mla_kv_lora_rank, true});
        } else if (split_attention_layout) {
            buffers.push_back({prefix + "q_proj.weight", model_dim * model_dim, true});
            buffers.push_back({prefix + "k_proj.weight", kv_dim * model_dim, true});
            buffers.push_back({prefix + "v_proj.weight", kv_dim * model_dim, true});
        } else {
            buffers.push_back({prefix + "qkv.weight", model_dim * model_dim * 3, true});
        }
        if (kv_pca_mode) {
            // The reference KV-PCA stages share one K and one V projection
            // across KV heads, then reconstruct each head before attention.
            buffers.push_back({prefix + "kv_pca_encode.k.weight", kv_pca_dim * head_dim, true});
            buffers.push_back({prefix + "kv_pca_encode.v.weight", kv_pca_dim * head_dim, true});
            buffers.push_back({prefix + "kv_pca_decode.k.weight", head_dim * kv_pca_dim, true});
            buffers.push_back({prefix + "kv_pca_decode.v.weight", head_dim * kv_pca_dim, true});
        }
        buffers.push_back({prefix + "attention_out.weight", model_dim * model_dim, true});
        if (normalized_id(cfg.template_name) == "diff-transformer" && layer == 0) {
            // DifferentialAttentionStage owns one shared learnable lambda.
            // Keep it in the persistent store so checkpoint/resume matches the
            // Python/Torch module contract instead of treating it as a CLI-only
            // constant.
            buffers.push_back({"attention.diff_lambda", 1, true});
        }
        if (normalized_id(cfg.template_name) == "deepseek-v4") {
            buffers.push_back({prefix + "residual.beta_logit.weight", model_dim, true});
        }
        buffers.push_back({prefix + "ffn_norm.weight", model_dim, true});
        if (per_layer_moe_layout) {
            buffers.push_back({prefix + "router.weight", model_dim * experts, true});
            if (native_family_uses_auxfree_moe_balance(family)) {
                buffers.push_back({prefix + "router.auxfree_bias.weight", experts, false});
            }
            buffers.push_back({prefix + "experts.gate_up.weight", expert_layer_copies * model_dim * hidden_dim * 2, true});
            buffers.push_back({prefix + "experts.down.weight", expert_layer_copies * hidden_dim * model_dim, true});
        } else {
            buffers.push_back({prefix + "ffn_gate_up.weight", model_dim * hidden_dim * 2, true});
            buffers.push_back({prefix + "ffn_down.weight", hidden_dim * model_dim, true});
        }
    }
    const auto add_semantic_jepa_encoder_backbone = [&](std::string_view encoder_name, bool trainable) {
        const std::string root = std::string(encoder_name) + ".backbone.";
        buffers.push_back({root + "token_embedding.weight", vocab * model_dim, trainable});
        buffers.push_back({root + "final_norm.weight", model_dim, trainable});
        for (std::int64_t layer = 0; layer < layers; ++layer) {
            const std::string prefix = root + "layers." + std::to_string(layer) + ".";
            buffers.push_back({prefix + "attention_norm.weight", model_dim, trainable});
            buffers.push_back({prefix + "q_proj.weight", model_dim * model_dim, trainable});
            buffers.push_back({prefix + "k_proj.weight", kv_dim * model_dim, trainable});
            buffers.push_back({prefix + "v_proj.weight", kv_dim * model_dim, trainable});
            buffers.push_back({prefix + "attention_out.weight", model_dim * model_dim, trainable});
            buffers.push_back({prefix + "ffn_norm.weight", model_dim, trainable});
            buffers.push_back({prefix + "router.weight", model_dim * experts, trainable});
            buffers.push_back({prefix + "experts.gate_up.weight",
                               expert_layer_copies * model_dim * hidden_dim * 2, trainable});
            buffers.push_back({prefix + "experts.down.weight",
                               expert_layer_copies * hidden_dim * model_dim, trainable});
        }
        const std::string semantic_root = std::string(encoder_name) + ".semantic_projector.";
        buffers.push_back({semantic_root + "topic_heads.weight",
                           kNativeSemanticCanonicalTotalTerms * model_dim, trainable});
        buffers.push_back({semantic_root + "sig_head.weight",
                           kNativeSemanticHashBuckets * model_dim, trainable});
        // The semantic projector residual output is surfaced for template shape
        // parity but the current semantic JEPA graph does not consume it. Keep
        // those buffers persistent while matching PyTorch's unused-parameter
        // behavior by leaving them out of AdamW until a real gradient path exists.
        buffers.push_back({semantic_root + "residual_head.0.weight",
                           kNativeSemanticProjectorResidualDims * model_dim, false});
        buffers.push_back({semantic_root + "residual_head.2.weight",
                           kNativeSemanticProjectorResidualDims * kNativeSemanticProjectorResidualDims,
                           false});
    };
    const auto add_semantic_chunk_projector = [&](std::string_view projector_name, bool trainable) {
        const std::string root = std::string(projector_name) + ".";
        buffers.push_back({root + "topic_heads.weight",
                           kNativeSemanticCanonicalTotalTerms * model_dim, trainable});
        buffers.push_back({root + "sig_head.weight",
                           kNativeSemanticHashBuckets * model_dim, trainable});
        // The residual tuple is surfaced by the Torch template, but native
        // router logic does not consume it yet. Keep the buffers persistent and
        // frozen until a real gradient path exists.
        buffers.push_back({root + "residual_head.0.weight",
                           kNativeSemanticProjectorResidualDims * model_dim, false});
        buffers.push_back({root + "residual_head.2.weight",
                           kNativeSemanticProjectorResidualDims * kNativeSemanticProjectorResidualDims,
                           false});
    };
    const auto add_nonsemantic_jepa_target_encoder_backbone = [&](bool use_moe) {
        const std::string root = "target_encoder.backbone.";
        constexpr bool trainable = false;
        buffers.push_back({root + "token_embedding.weight", vocab * model_dim, trainable});
        buffers.push_back({root + "final_norm.weight", model_dim, trainable});
        for (std::int64_t layer = 0; layer < layers; ++layer) {
            const std::string prefix = root + "layers." + std::to_string(layer) + ".";
            buffers.push_back({prefix + "attention_norm.weight", model_dim, trainable});
            buffers.push_back({prefix + "q_proj.weight", model_dim * model_dim, trainable});
            buffers.push_back({prefix + "k_proj.weight", kv_dim * model_dim, trainable});
            buffers.push_back({prefix + "v_proj.weight", kv_dim * model_dim, trainable});
            buffers.push_back({prefix + "attention_out.weight", model_dim * model_dim, trainable});
            buffers.push_back({prefix + "ffn_norm.weight", model_dim, trainable});
            if (use_moe) {
                buffers.push_back({prefix + "router.weight", model_dim * experts, trainable});
                buffers.push_back({prefix + "experts.gate_up.weight",
                                   expert_layer_copies * model_dim * hidden_dim * 2, trainable});
                buffers.push_back({prefix + "experts.down.weight",
                                   expert_layer_copies * hidden_dim * model_dim, trainable});
            } else {
                buffers.push_back({prefix + "ffn_gate_up.weight", model_dim * hidden_dim * 2, trainable});
                buffers.push_back({prefix + "ffn_down.weight", hidden_dim * model_dim, trainable});
            }
        }
        const std::string projector_root = "target_encoder.projector.";
        buffers.push_back({projector_root + "net.0.weight", model_dim * model_dim, trainable});
        buffers.push_back({projector_root + "net.1.weight", model_dim, trainable});
        buffers.push_back({projector_root + "net.1.bias", model_dim, trainable});
        buffers.push_back({projector_root + "net.3.weight", model_dim * model_dim, trainable});
    };
    const bool semantic_jepa_encoder_layout = is_semantic_moe_template(cfg);
    if (semantic_jepa_encoder_layout) {
        add_semantic_jepa_encoder_backbone("jepa_online_encoder", true);
        // Torch training copies online encoder state into the target encoder and
        // freezes the target. Persist the target surface, but keep it out of AdamW
        // until the native EMA refresh path is wired.
        add_semantic_jepa_encoder_backbone("jepa_target_encoder", false);
        add_semantic_chunk_projector("online_chunk_projector", true);
        add_semantic_chunk_projector("target_chunk_projector", false);
        buffers.push_back({"jepa_semantic_predictor.net.0.weight",
                           kNativeSemanticPredictorHiddenDims * kNativeSemanticProjectorSemanticDims,
                           true});
        buffers.push_back({"jepa_semantic_predictor.net.2.weight",
                           kNativeSemanticProjectorSemanticDims * kNativeSemanticPredictorHiddenDims,
                           true});
    }
    const bool dense_jepa_target_backbone_layout =
        !is_semantic_family(family) &&
        family.find("jepa") != std::string::npos;
    if (dense_jepa_target_backbone_layout) {
        // Non-semantic JEPA templates own a target_encoder subgraph with its own
        // hidden backbone and projector. MoE-JEPA uses router/expert layers in
        // that frozen target surface; dense JEPA uses the dense FFN layout.
        add_nonsemantic_jepa_target_encoder_backbone(family.find("moe") != std::string::npos);
    }
    if (!per_layer_moe_layout && (family.find("moe") != std::string::npos || family.find("mixllama") != std::string::npos ||
        family.find("deepseek") != std::string::npos)) {
        buffers.push_back({"router.weight", model_dim * experts, true});
        buffers.push_back({"router.topk_scale", top_k, true});
        if (native_family_uses_auxfree_moe_balance(family)) {
            buffers.push_back({"router.auxfree_bias.weight", experts, false});
        }
        buffers.push_back({"experts.gate_up.weight", expert_layer_copies * model_dim * hidden_dim * 2, true});
        buffers.push_back({"experts.down.weight", expert_layer_copies * hidden_dim * model_dim, true});
    }
    if (family.find("jepa") != std::string::npos && !semantic_jepa_encoder_layout) {
        buffers.push_back({"jepa_target_encoder.weight", model_dim * model_dim,
                           !dense_jepa_target_backbone_layout});
        if (is_semantic_family(family)) {
            buffers.push_back({"jepa_online_encoder.weight", model_dim * model_dim, true});
        }
        buffers.push_back({"jepa_projector.weight", model_dim * model_dim, true});
        buffers.push_back({"jepa_predictor.weight", model_dim * model_dim, true});
    }
    if (is_semantic_family(family)) {
        buffers.push_back({"semantic_planner.weight", model_dim * model_dim, true});
        buffers.push_back({"semantic_alignment.weight", model_dim * model_dim, true});
        buffers.push_back({"semantic_vocab_projection.weight", semantic_vocab_dims * model_dim, true});
        if (native_family_semantic_per_term_topic_head_supported(semantic_vocab_dims)) {
            buffers.push_back({"semantic_projector.topic_heads.weight",
                               kNativeSemanticCanonicalTotalTerms * model_dim, true});
            buffers.push_back({"semantic_projector.sig_head.weight",
                               kNativeSemanticHashBuckets * model_dim, true});
            // The route-time semantic projector exposes the template residual
            // head, but that residual tuple output is not consumed by the
            // router graph. Persist it and keep it out of AdamW until a real
            // gradient path exists.
            buffers.push_back({"semantic_projector.residual_head.0.weight",
                               kNativeSemanticProjectorResidualDims * model_dim, false});
            buffers.push_back({"semantic_projector.residual_head.2.weight",
                               kNativeSemanticProjectorResidualDims * kNativeSemanticProjectorResidualDims,
                               false});
        } else {
            buffers.push_back({"semantic_chunk_topic_head.weight", semantic_vocab_dims * model_dim, true});
        }
        buffers.push_back({"semantic_hash.proj.weight",
                           kNativeSemanticHashTables * kNativeSemanticHashPlanes * semantic_vocab_dims, false});
        buffers.push_back({"semantic_hash_embed.weight",
                           kNativeSemanticHashBuckets * semantic_vocab_dims, true});
        buffers.push_back({"semantic_table_gate.weight", kNativeSemanticHashTables, true});
        buffers.push_back({"semantic_dimension_bias.weight", semantic_vocab_dims, true});
        if (semantic_shared_experts > 0) {
            buffers.push_back({"semantic_router.shared_logits", semantic_shared_experts, true});
        }
        if (semantic_free_experts > 0) {
            buffers.push_back({"semantic_router.free_head.weight",
                               semantic_free_experts * semantic_route_dims, true});
            buffers.push_back({"semantic_router.free_head.bias", semantic_free_experts, true});
        }
    }
    if (family.find("seq2seq") != std::string::npos) {
        buffers.push_back({"encoder.layers.qkv.weight", layers * model_dim * model_dim * 3, true});
        buffers.push_back({"decoder.cross_attention.qkv.weight", layers * model_dim * model_dim * 3, true});
    }
    if (family.find("diffusion") != std::string::npos) {
        buffers.push_back({"denoise_head.weight", vocab * model_dim, true});
    }
    if (family.find("ttt") != std::string::npos) {
        const std::int64_t ttt_hidden_dim = family_ttt_hidden_dim(cfg);
        buffers.push_back({"ttt.inner_base.weight", model_dim * model_dim, true});
        buffers.push_back({"ttt.inner_down.weight", model_dim * ttt_hidden_dim, true});
        buffers.push_back({"ttt.inner_up.weight", ttt_hidden_dim * model_dim, true});
    }
    if (family.find("universal") != std::string::npos) {
        buffers.push_back({"universal.recurrent.weight", model_dim * model_dim, true});
        buffers.push_back({"universal.halt_gate.weight", model_dim, true});
    }
    if (family.find("hnet") != std::string::npos) {
        const std::int64_t patch_size = family_byte_patch_size(cfg);
        buffers.push_back({"byte_patch_embed.weight", 256 * model_dim, true});
        buffers.push_back({"byte_patch_merge.weight", patch_size * model_dim * model_dim, true});
    }
    if (family.find("jamba") != std::string::npos) {
        buffers.push_back({"mamba.in_proj.weight", model_dim * model_dim * 2, true});
        buffers.push_back({"mamba.state.weight", model_dim * model_dim, true});
    }
    return buffers;
}

std::int64_t parameter_layout_model_dim(const std::vector<ParameterBufferSpec>& buffers) {
    for (const ParameterBufferSpec& buffer : buffers) {
        if (buffer.name == "final_norm.weight" && buffer.elements > 0) {
            return buffer.elements;
        }
    }
    return 768;
}

std::int64_t parameter_layout_vocab_size(const std::vector<ParameterBufferSpec>& buffers) {
    const std::int64_t model_dim = parameter_layout_model_dim(buffers);
    if (model_dim <= 0) {
        return 50304;
    }
    for (const ParameterBufferSpec& buffer : buffers) {
        if (buffer.name == "token_embedding.weight" && buffer.elements > 0) {
            return std::max<std::int64_t>(1, buffer.elements / model_dim);
        }
    }
    return 50304;
}

std::int64_t parameter_element_count(const std::vector<ParameterBufferSpec>& buffers) {
    std::int64_t total = 0;
    for (const ParameterBufferSpec& buffer : buffers) {
        total += buffer.elements;
    }
    return total;
}

struct NativeFamilyParameterRoleCounts {
    std::int64_t total = 0;
    std::int64_t base_transformer = 0;
    std::int64_t moe = 0;
    std::int64_t jepa = 0;
    std::int64_t semantic = 0;
    std::int64_t seq2seq = 0;
    std::int64_t diffusion = 0;
    std::int64_t ttt = 0;
    std::int64_t universal = 0;
    std::int64_t hnet = 0;
    std::int64_t jamba = 0;
};

struct NativeFamilyProductionStepDescriptor {
    std::string family;
    std::string implementation;
    std::vector<std::string> required_roles;
    std::vector<std::string> planned_stages;
    bool full_geometry_forward_backward = false;
    bool auxfree_moe_balance = false;
};

NativeFamilyParameterRoleCounts native_family_parameter_role_counts(
    const std::vector<ParameterBufferSpec>& buffers) {
    NativeFamilyParameterRoleCounts counts;
    counts.total = static_cast<std::int64_t>(buffers.size());
    for (const ParameterBufferSpec& buffer : buffers) {
        const std::string& name = buffer.name;
        if ((name.starts_with("layers.") &&
             (name.find(".router.") != std::string::npos ||
              name.find(".experts.") != std::string::npos)) ||
            name.starts_with("router.") || name.starts_with("experts.")) {
            counts.moe += 1;
        } else if (name == "token_embedding.weight" ||
            name == "final_norm.weight" ||
            name == "lm_head.weight" ||
            name == "attention.diff_lambda" ||
            name.starts_with("layers.")) {
            counts.base_transformer += 1;
        } else if (name.starts_with("jepa_") || name.starts_with("target_encoder.")) {
            counts.jepa += 1;
        } else if (name.starts_with("semantic_")) {
            counts.semantic += 1;
        } else if (name.starts_with("encoder.") || name.starts_with("decoder.")) {
            counts.seq2seq += 1;
        } else if (name.starts_with("diffusion_") || name.starts_with("denoise_")) {
            counts.diffusion += 1;
        } else if (name.starts_with("ttt.")) {
            counts.ttt += 1;
        } else if (name.starts_with("universal.")) {
            counts.universal += 1;
        } else if (name.starts_with("byte_patch_")) {
            counts.hnet += 1;
        } else if (name.starts_with("mamba.")) {
            counts.jamba += 1;
        }
    }
    return counts;
}

std::int64_t native_family_parameter_role_count(
    const NativeFamilyParameterRoleCounts& counts,
    std::string_view role) {
    if (role == "base_transformer") {
        return counts.base_transformer;
    }
    if (role == "moe") {
        return counts.moe;
    }
    if (role == "jepa") {
        return counts.jepa;
    }
    if (role == "semantic") {
        return counts.semantic;
    }
    if (role == "seq2seq") {
        return counts.seq2seq;
    }
    if (role == "diffusion") {
        return counts.diffusion;
    }
    if (role == "ttt") {
        return counts.ttt;
    }
    if (role == "universal") {
        return counts.universal;
    }
    if (role == "hnet") {
        return counts.hnet;
    }
    if (role == "jamba") {
        return counts.jamba;
    }
    return 0;
}

NativeFamilyProductionStepDescriptor native_family_production_step_descriptor(const Config& cfg) {
    const std::string family =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    const std::string preset = normalized_id(cfg.template_name);
    NativeFamilyProductionStepDescriptor descriptor;
    descriptor.implementation = native_full_geometry_build_enabled()
        ? "persistent_tile_llama_full_geometry_forward_backward"
        : native_full_moe_geometry_build_enabled()
            ? (std::string_view(NFN_NATIVE_MODEL_FAMILY) == "jamba"
                ? "persistent_tile_jamba_full_geometry_forward_backward"
                : std::string_view(NFN_NATIVE_MODEL_FAMILY) == "semantic-router-moe"
                ? "persistent_tile_semantic_router_moe_full_geometry_forward_backward"
                : std::string_view(NFN_NATIVE_MODEL_FAMILY) == "moe-jepa-evo"
                    ? "persistent_tile_moe_jepa_full_geometry_forward_backward"
                : "persistent_tile_moe_full_geometry_forward_backward")
        : native_full_jepa_geometry_build_enabled()
            ? "persistent_tile_jepa_full_geometry_forward_backward"
        : native_full_specialized_geometry_build_enabled()
            ? (native_hnet_graph_build_enabled()
                ? "persistent_tile_hnet_byte_patch_full_geometry_forward_backward"
                : native_universal_graph_build_enabled()
                    ? "persistent_tile_universal_recurrent_full_geometry_forward_backward"
                : native_diffusion_graph_build_enabled()
                    ? "persistent_tile_diffusion_full_geometry_forward_backward"
                : native_ttt_graph_build_enabled()
                    ? "persistent_tile_ttt_full_geometry_forward_backward"
                : native_seq2seq_graph_build_enabled()
                    ? "persistent_tile_seq2seq_full_geometry_forward_backward"
                : "persistent_tile_jamba_full_geometry_forward_backward")
        : "persistent_sampled_lm_chained_block_routed_moe_jepa_semantic_specialized_bridge";
    descriptor.full_geometry_forward_backward = native_full_family_geometry_build_enabled();
    descriptor.auxfree_moe_balance = native_family_uses_auxfree_moe_balance(family);
    if (family.find("hnet") != std::string::npos) {
        descriptor.family = "hnet";
        descriptor.required_roles = {"base_transformer", "hnet"};
        descriptor.planned_stages = {
            "byte_patch_embed",
            "transformer_backbone_forward",
            "byte_patch_merge",
            "byte_lm_head",
            "byte_cross_entropy_backward",
            "transformer_backbone_backward",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("semantic") != std::string::npos &&
               (family.find("moe") != std::string::npos || family.find("router") != std::string::npos)) {
        descriptor.family = "semantic_router_moe";
        descriptor.required_roles = {"base_transformer", "moe", "semantic"};
        if (family.find("jepa") != std::string::npos) {
            descriptor.required_roles.push_back("jepa");
        }
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "semantic_target_projection",
            "router_topk",
            "moe_swiglu",
            "route_weight_backward",
            "jepa_latent_branch",
            "lm_head_and_semantic_losses",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("semantic") != std::string::npos && family.find("jepa") != std::string::npos) {
        descriptor.family = "semantic_dense_jepa";
        descriptor.required_roles = {"base_transformer", "jepa", "semantic"};
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "dense_swiglu",
            "jepa_latent_branch",
            "semantic_alignment_loss",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("jepa") != std::string::npos &&
               (family.find("moe") != std::string::npos || family.find("mixllama") != std::string::npos)) {
        descriptor.family = "moe_jepa";
        descriptor.required_roles = {"base_transformer", "moe", "jepa"};
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "router_topk",
            "moe_swiglu",
            "route_weight_backward",
            "jepa_latent_branch",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("moe") != std::string::npos ||
               family.find("mixllama") != std::string::npos ||
               family.find("deepseek") != std::string::npos) {
        descriptor.family = preset == "deepseek-v4"
            ? "deepseek_v4"
            : family_uses_mla(cfg)
                ? "deepseek_v3"
                : "mixllama";
        descriptor.required_roles = {"base_transformer", "moe"};
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "router_topk",
            "moe_swiglu",
            "route_weight_backward",
            "lm_head",
            "shared_many_tensor_adamw",
        };
        if (family_uses_qk_norm(cfg)) {
            descriptor.planned_stages.insert(descriptor.planned_stages.begin() + 2, "qk_norm");
        }
        if (preset == "deepseek-v4") {
            descriptor.planned_stages.insert(descriptor.planned_stages.begin() + 3, "mhc_residual");
        }
    } else if (family.find("seq2seq") != std::string::npos) {
        descriptor.family = "seq2seq";
        descriptor.required_roles = {"base_transformer", "seq2seq"};
        descriptor.planned_stages = {
            "encoder_self_attention",
            "decoder_cross_attention",
            "lm_head",
            "token_cross_entropy_backward",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("diffusion") != std::string::npos) {
        descriptor.family = "diffusion";
        descriptor.required_roles = {"base_transformer", "diffusion"};
        descriptor.planned_stages = {
            "token_embedding",
            "deterministic_timestep_mask_scheduler",
            "masked_denoise_objective",
            "denoise_head_backward",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("ttt") != std::string::npos) {
        descriptor.family = "ttt_llama";
        descriptor.required_roles = {"base_transformer", "ttt"};
        descriptor.planned_stages = {
            "token_embedding",
            "base_transformer_step",
            "ttt_inner_down_up_update",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("universal") != std::string::npos) {
        descriptor.family = "universal_llama";
        descriptor.required_roles = {"base_transformer", "universal"};
        descriptor.planned_stages = {
            "token_embedding",
            "recurrent_shared_block",
            "act_halting_gate",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("jamba") != std::string::npos) {
        descriptor.family = "jamba";
        descriptor.required_roles = {"base_transformer", "jamba"};
        descriptor.planned_stages = {
            "token_embedding",
            "mamba_chunk_state",
            "attention_moe_layer",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else if (family.find("jepa") != std::string::npos) {
        descriptor.family = "dense_jepa";
        descriptor.required_roles = {"base_transformer", "jepa"};
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "dense_swiglu",
            "jepa_latent_branch",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    } else {
        descriptor.family = "llama";
        descriptor.required_roles = {"base_transformer"};
        descriptor.planned_stages = {
            "token_embedding",
            "rmsnorm_gqa_qkv_attention",
            "dense_swiglu",
            "lm_head",
            "shared_many_tensor_adamw",
        };
    }
    if (family_uses_megakernel(cfg)) {
        descriptor.planned_stages[1] = "fused_causal_attention";
    } else if (family_uses_mla(cfg)) {
        descriptor.planned_stages[1] = "multi_latent_attention";
    } else if (preset == "diff-transformer") {
        descriptor.planned_stages[1] = "differential_attention";
    } else if (family_uses_kv_pca(cfg)) {
        descriptor.planned_stages[1] = "kv_pca_encode_decode_attention";
    } else if (family_attention_geometry(cfg).use_sparse_rules) {
        descriptor.planned_stages[1] = "native_sparse_attention";
    }
    return descriptor;
}

bool validate_native_family_parameter_role_bindings(
    const neuralfn::native_train::FamilyDeviceParameterStore& parameters,
    const std::vector<ParameterBufferSpec>& buffers,
    NativeFamilyParameterRoleCounts* counts,
    std::string* error) {
    if (counts == nullptr || error == nullptr) {
        return false;
    }
    *counts = native_family_parameter_role_counts(buffers);
    for (const ParameterBufferSpec& expected : buffers) {
        const neuralfn::native_train::FamilyDeviceParameterView view =
            parameters.parameter_view(expected.name);
        if (view.name.empty()) {
            *error = "native family production role binding missing parameter " + expected.name;
            return false;
        }
        if (view.elements != expected.elements || view.trainable != expected.trainable) {
            *error = "native family production role binding metadata mismatch for " + expected.name;
            return false;
        }
        if (!view.valid()) {
            *error = "native family production role binding has no device storage for " + expected.name;
            return false;
        }
    }
    return true;
}

std::vector<neuralfn::native_train::FamilyParameterBufferSpec> family_production_parameter_specs(
    const std::vector<ParameterBufferSpec>& buffers) {
    std::vector<neuralfn::native_train::FamilyParameterBufferSpec> specs;
    specs.reserve(buffers.size());
    for (const ParameterBufferSpec& buffer : buffers) {
        specs.push_back({buffer.name, buffer.elements, buffer.trainable});
    }
    return specs;
}

float native_family_dense_base_initializer(std::string_view buffer_name, std::int64_t element_index) {
    return native_family_dense_base_value(buffer_name, element_index);
}

double native_family_numpy_mt19937_double(std::mt19937* rng) {
    const std::uint32_t upper = (*rng)() >> 5;
    const std::uint32_t lower = (*rng)() >> 6;
    return (static_cast<double>(upper) * 67108864.0 + static_cast<double>(lower)) *
           (1.0 / 9007199254740992.0);
}

std::vector<float> native_family_numpy_seeded_semantic_hash_projection(std::int64_t semantic_vocab_dims) {
    const std::int64_t dims = std::max<std::int64_t>(1, semantic_vocab_dims);
    const std::int64_t elements = kNativeSemanticHashTables * kNativeSemanticHashPlanes * dims;
    std::vector<float> values(static_cast<std::size_t>(elements), 0.0f);
    std::mt19937 rng(42);
    bool has_gauss = false;
    double cached_gauss = 0.0;
    for (std::int64_t index = 0; index < elements; ++index) {
        double value = 0.0;
        if (has_gauss) {
            has_gauss = false;
            value = cached_gauss;
        } else {
            double x1 = 0.0;
            double x2 = 0.0;
            double radius = 0.0;
            do {
                x1 = 2.0 * native_family_numpy_mt19937_double(&rng) - 1.0;
                x2 = 2.0 * native_family_numpy_mt19937_double(&rng) - 1.0;
                radius = x1 * x1 + x2 * x2;
            } while (radius >= 1.0 || radius == 0.0);
            const double scale = std::sqrt(-2.0 * std::log(radius) / radius);
            cached_gauss = scale * x1;
            has_gauss = true;
            value = scale * x2;
        }
        values[static_cast<std::size_t>(index)] = static_cast<float>(value);
    }
    return values;
}

bool overwrite_native_family_seeded_semantic_hash_projection(
    neuralfn::native_train::FamilyDeviceParameterStore* parameters,
    const Config& cfg,
    std::string* error) {
    if (parameters == nullptr || error == nullptr) {
        return false;
    }
    const std::string family =
        normalized_id(std::string(NFN_NATIVE_MODEL_FAMILY) + "-" + cfg.template_name);
    if (!is_semantic_family(family)) {
        return true;
    }
    return parameters->overwrite_buffer_from_host(
        "semantic_hash.proj.weight",
        native_family_numpy_seeded_semantic_hash_projection(
            clamp_positive(cfg.semantic_vocab_dims, 86)),
        error);
}

