[[maybe_unused]]
NativeFamilyProductionState build_native_family_production_state(
    const Config& cfg,
    const std::filesystem::path& resolved_resume_sidecar,
    std::string_view tile_ops_lib,
    std::string_view cuda_runtime_lib) {
    NativeFamilyProductionState state;
    const std::vector<ParameterBufferSpec> buffers = family_parameter_buffers(cfg);
    state.parameter_role_counts = native_family_parameter_role_counts(buffers);
    state.parameter_specs = family_production_parameter_specs(buffers);
    state.parameter_elements = parameter_element_count(buffers);
    constexpr std::int64_t kFloat32Bytes = 4;
    if (state.parameter_elements <= 0 ||
        state.parameter_elements > std::numeric_limits<std::int64_t>::max() / kFloat32Bytes) {
        state.error = "native family production parameter layout is invalid";
        return state;
    }
    state.parameter_bytes = state.parameter_elements * kFloat32Bytes;
    state.parameters = neuralfn::native_train::FamilyDeviceParameterStore(state.parameter_specs);

    if (!resolved_resume_sidecar.empty()) {
        state.parameter_store_initialized =
            state.parameters.load_from_sidecar(resolved_resume_sidecar, cuda_runtime_lib, &state.error);
        state.resume_sidecar_loaded = state.parameter_store_initialized;
    } else {
        state.parameter_store_initialized = state.parameters.initialize_deterministic(
            native_family_dense_base_initializer,
            cuda_runtime_lib,
            &state.error);
        if (state.parameter_store_initialized && normalized_id(cfg.template_name) == "diff-transformer") {
            state.parameter_store_initialized = state.parameters.overwrite_buffer_from_host(
                "attention.diff_lambda",
                std::vector<float>{static_cast<float>(cfg.differential_lambda)},
                &state.error);
        }
        if (state.parameter_store_initialized) {
            state.parameter_store_initialized =
                overwrite_native_family_seeded_semantic_hash_projection(
                    &state.parameters, cfg, &state.error);
        }
    }
    if (!state.parameter_store_initialized) {
        return state;
    }
    state.parameters.reserve_temporary_metadata_records(256);
    state.parameter_role_binding_verified = validate_native_family_parameter_role_bindings(
        state.parameters,
        buffers,
        &state.parameter_role_counts,
        &state.error);
    if (!state.parameter_role_binding_verified) {
        return state;
    }
    std::vector<float> host_parameters;
    if (!state.parameters.copy_to_host(&host_parameters, &state.error)) {
        return state;
    }
    for (std::int64_t index = 0; index < static_cast<std::int64_t>(host_parameters.size()); ++index) {
        mix_native_family_float_checksum(
            &state.parameter_store_checksum,
            index,
            host_parameters[static_cast<std::size_t>(index)]);
    }
    state.parameter_store_checksum_computed = true;
    state.production_step_parameter_store_checksum = state.parameter_store_checksum;
    state.production_step_parameter_store_checksum_computed = true;
    state.temporary_pool_buffer_count = state.parameters.temporary_pool_buffer_count();
    state.temporary_active_buffer_count = state.parameters.temporary_active_buffer_count();
    state.temporary_metadata_reserved_buffer_count =
        state.parameters.temporary_metadata_reserved_buffer_count();
    state.temporary_active_buffer_high_water_count =
        state.parameters.temporary_active_buffer_high_water_count();

    state.optimizer = neuralfn::native_train::FamilyOptimizerState(
        state.parameters.buffers(),
        static_cast<float>(cfg.weight_decay));
    state.optimizer.set_cuda_graph_capture_enabled(native_family_cuda_graph_capture_enabled());
    state.optimizer_allocated = state.optimizer.allocate(cuda_runtime_lib, tile_ops_lib, &state.error);
    if (state.optimizer_allocated && state.resume_sidecar_loaded) {
        const std::filesystem::path optimizer_path =
            native_family_optimizer_path_from_parameter_path(resolved_resume_sidecar);
        std::error_code optimizer_ec;
        if (std::filesystem::is_regular_file(optimizer_path, optimizer_ec)) {
            state.optimizer_state_loaded = state.optimizer.load_checkpoint(
                optimizer_path, &state.resumed_optimizer_steps, &state.error);
            if (!state.optimizer_state_loaded) {
                state.optimizer_allocated = false;
            }
        }
    }
    state.optimizer_bf16_shadow_enabled = state.optimizer.bf16_shadow_enabled();
    state.cuda_graph_capture_enabled = state.optimizer.cuda_graph_capture_enabled();
    state.cuda_graph_capture_supported = state.optimizer.supports_cuda_graph_capture();
    state.optimizer_cuda_graph_device_hyperparameters_supported =
        state.optimizer.cuda_graph_device_hyperparameters_supported();
    state.optimizer_cuda_graph_uses_device_hyperparameters =
        state.optimizer.cuda_graph_uses_device_hyperparameters();
    state.production_step_cuda_stream_supported = state.optimizer.supports_production_step_stream();
    state.bf16_shadow_elements = state.optimizer.bf16_shadow_elements();
    return state;
}

