std::unique_ptr<neuralfn::native_train::FamilyProductionStep> make_native_family_production_step(
    const Config& cfg,
    std::string_view step_name);

NativeFamilyProductionBootstrap prepare_native_family_production_bootstrap(
    const Config& cfg,
    const char* program) {
    NativeFamilyProductionBootstrap bootstrap;
    bootstrap.router_aux_loss_coef = cfg.router_aux_loss_coef;
    const std::vector<ParameterBufferSpec> buffers = family_parameter_buffers(cfg);
    bootstrap.parameter_role_counts = native_family_parameter_role_counts(buffers);
    bootstrap.parameter_elements = parameter_element_count(buffers);
    constexpr std::int64_t kFloat32Bytes = 4;
    bootstrap.parameter_bytes =
        bootstrap.parameter_elements > 0 &&
                bootstrap.parameter_elements <= std::numeric_limits<std::int64_t>::max() / kFloat32Bytes
            ? bootstrap.parameter_elements * kFloat32Bytes
            : -1;
    if (!bootstrap.required) {
        return bootstrap;
    }

    bootstrap.attempted = true;
    bootstrap.requested_checkpoint = cfg.native_checkpoint;
    bootstrap.tile_ops_lib = resolve_tile_ops_lib(cfg, program);
    bootstrap.full_step_forward_backward_launch_sequence_capture_eligible =
        !native_family_has_specialty_capture_host_control(NFN_NATIVE_MODEL_FAMILY);
    std::filesystem::path resolved_resume_sidecar;
    if (!cfg.native_checkpoint.empty()) {
        std::string resolve_error;
        resolved_resume_sidecar =
            resolve_native_family_resume_parameter_path(std::filesystem::path(cfg.native_checkpoint), &resolve_error);
        if (resolved_resume_sidecar.empty()) {
            bootstrap.error = resolve_error;
            return bootstrap;
        }
        bootstrap.resolved_resume_sidecar = resolved_resume_sidecar.string();
    }

    std::string last_error;
    for (const std::string& cuda_runtime_lib : cuda_runtime_candidates(cfg)) {
        NativeFamilyProductionState candidate =
            build_native_family_production_state(cfg, resolved_resume_sidecar, bootstrap.tile_ops_lib, cuda_runtime_lib);
        if (candidate.parameter_store_initialized && candidate.optimizer_allocated) {
            bootstrap.cuda_runtime_lib = cuda_runtime_lib;
            bootstrap.parameter_store_initialized = candidate.parameter_store_initialized;
            bootstrap.resume_sidecar_loaded = candidate.resume_sidecar_loaded;
            bootstrap.optimizer_state_loaded = candidate.optimizer_state_loaded;
            bootstrap.resumed_optimizer_steps = candidate.resumed_optimizer_steps;
            bootstrap.optimizer_allocated = candidate.optimizer_allocated;
            bootstrap.optimizer_bf16_shadow_enabled = candidate.optimizer_bf16_shadow_enabled;
            bootstrap.cuda_graph_capture_enabled = candidate.cuda_graph_capture_enabled;
            bootstrap.cuda_graph_capture_supported = candidate.cuda_graph_capture_supported;
            bootstrap.optimizer_cuda_graph_device_hyperparameters_supported =
                candidate.optimizer_cuda_graph_device_hyperparameters_supported;
            bootstrap.optimizer_cuda_graph_uses_device_hyperparameters =
                candidate.optimizer_cuda_graph_uses_device_hyperparameters;
            bootstrap.production_step_cuda_stream_supported =
                candidate.production_step_cuda_stream_supported;
            bootstrap.full_step_forward_backward_launch_sequence_stream_ordered =
                candidate.full_step_forward_backward_launch_sequence_stream_ordered;
            bootstrap.full_step_forward_backward_launch_sequence_capture_eligible =
                !native_family_has_specialty_capture_host_control(NFN_NATIVE_MODEL_FAMILY);
            bootstrap.full_step_forward_backward_graph_replay_ready =
                candidate.full_step_forward_backward_graph_replay_ready;
            bootstrap.full_step_forward_backward_graph_capture_count =
                candidate.full_step_forward_backward_graph_capture_count;
            bootstrap.full_step_forward_backward_graph_replay_count =
                candidate.full_step_forward_backward_graph_replay_count;
            bootstrap.temporary_pool_buffer_count = candidate.temporary_pool_buffer_count;
            bootstrap.temporary_active_buffer_count = candidate.temporary_active_buffer_count;
            bootstrap.temporary_metadata_reserved_buffer_count =
                candidate.temporary_metadata_reserved_buffer_count;
            bootstrap.temporary_active_buffer_high_water_count =
                candidate.temporary_active_buffer_high_water_count;
            bootstrap.parameter_role_binding_verified = candidate.parameter_role_binding_verified;
            bootstrap.parameter_role_counts = candidate.parameter_role_counts;
            bootstrap.parameter_elements = candidate.parameter_elements;
            bootstrap.parameter_bytes = candidate.parameter_bytes;
            bootstrap.bf16_shadow_elements = candidate.bf16_shadow_elements;
            bootstrap.parameter_store_checksum = candidate.parameter_store_checksum;
            bootstrap.parameter_store_checksum_computed = candidate.parameter_store_checksum_computed;
            bootstrap.production_step_parameter_store_checksum =
                candidate.production_step_parameter_store_checksum;
            bootstrap.production_step_parameter_store_checksum_count =
                candidate.production_step_parameter_store_checksum_count;
            bootstrap.production_step_parameter_store_checksum_computed =
                candidate.production_step_parameter_store_checksum_computed;
            bootstrap.production_step_parameter_store_checksum_changed =
                candidate.production_step_parameter_store_checksum_changed;
            bootstrap.ready = true;
            bootstrap.state = std::move(candidate);
            bootstrap.production_step = make_native_family_production_step(
                cfg, normalized_id(cfg.template_name));
            if (bootstrap.production_step == nullptr) {
                bootstrap.ready = false;
                bootstrap.error = "native family production step factory returned null during bootstrap";
                return bootstrap;
            }
            return bootstrap;
        }
        last_error = candidate.error;
    }
    bootstrap.error = last_error.empty()
        ? "native family production bootstrap could not resolve a CUDA runtime"
        : last_error;
    return bootstrap;
}

