bool load_native_family_tile_lm_api(
    std::string_view tile_ops_lib_override,
    const Config& cfg,
    NativeFamilyTileLmApi* api,
    std::string* error) {
    if (api == nullptr || error == nullptr) {
        return false;
    }
    *api = NativeFamilyTileLmApi{};
    const std::string tile_ops_path = tile_ops_lib_override.empty()
        ? resolve_tile_ops_lib(cfg, "nfn-native-family")
        : std::string(tile_ops_lib_override);
    api->handle = dlopen(tile_ops_path.c_str(), RTLD_NOW | RTLD_LOCAL);
    if (api->handle == nullptr) {
        const char* raw = dlerror();
        *error = raw == nullptr ? "failed to load Tile ops library for native family LM step" : raw;
        return false;
    }
    api->token_embedding = load_symbol<NativeFamilyTileLmApi::TokenEmbeddingU16Fn>(
        api->handle, "nfn_native_tile_token_embedding_u16_float32");
    api->linear = load_symbol<NativeFamilyTileLmApi::LinearFn>(
        api->handle, "nfn_native_tile_linear_float32");
    api->linear_backward_input = load_symbol<NativeFamilyTileLmApi::LinearBackwardInputFn>(
        api->handle, "nfn_native_tile_linear_backward_input_float32");
    api->linear_backward_weight = load_symbol<NativeFamilyTileLmApi::LinearBackwardWeightFn>(
        api->handle, "nfn_native_tile_linear_backward_weight_float32");
    api->token_embedding_backward_weight = load_symbol<NativeFamilyTileLmApi::TokenEmbeddingBackwardWeightU16Fn>(
        api->handle, "nfn_native_tile_token_embedding_backward_weight_u16_float32");
    api->ce_partials = load_symbol<NativeFamilyTileLmApi::CrossEntropyPartialsFn>(
        api->handle, "nfn_native_tile_token_cross_entropy_partials_float32");
    api->ce_backward = load_symbol<NativeFamilyTileLmApi::CrossEntropyBackwardFn>(
        api->handle, "nfn_native_tile_token_cross_entropy_backward_float32");
    api->fill = load_symbol<NativeFamilyTileLmApi::FillFn>(
        api->handle, "nfn_native_tile_fill_float32");
    if (api->token_embedding == nullptr || api->linear == nullptr ||
        api->linear_backward_input == nullptr || api->linear_backward_weight == nullptr ||
        api->token_embedding_backward_weight == nullptr || api->ce_partials == nullptr ||
        api->ce_backward == nullptr || api->fill == nullptr) {
        *error = "Tile ops library is missing native family token-LM forward/backward symbols";
        dlclose(api->handle);
        *api = NativeFamilyTileLmApi{};
        return false;
    }
    return true;
}

