    const std::int64_t differential_q_elements = differential_q_rows * (head_dim / 2);
    const std::int64_t differential_k_elements = rows * kv_heads * (head_dim / 2);
    const std::int64_t kv_pca_dim = family_kv_pca_compressed_dim(cfg);
