    const std::int64_t mla_q_rope_elements = mla_kv_rows * mla_rope_dim;
    const std::int64_t mla_kv_c_elements = rows * mla_kv_lora_rank;
    const std::int64_t mla_k_rope_elements = rows * mla_rope_dim;
    const std::int64_t mla_k_rope_heads_elements = mla_kv_rows * mla_rope_dim;
