    float* device_backbone_output = nullptr;
    float* device_backbone_norm_unscaled = nullptr;
    float* device_backbone_norm = nullptr;
    float* device_grad_backbone_output = nullptr;
    float* device_grad_backbone_norm = nullptr;
    float* device_inv_freq = nullptr;
    float* device_scale = nullptr;
    float* device_norm_zero = nullptr;
    float* device_norm_weight_gradient_matrix = nullptr;
    float* final_norm_weight_gradient_device = nullptr;
    float* device_prediction = nullptr;
    float* device_logits = nullptr;
    float* device_lm_loss = nullptr;
    float* device_lm_loss_reduced = nullptr;
