        const float* attention_norm_weight = parameters.parameter_ptr(prefix + "attention_norm.weight");
        const float* q_weight = parameters.parameter_ptr(prefix + "q_proj.weight");
        const float* k_weight = parameters.parameter_ptr(prefix + "k_proj.weight");
        const float* v_weight = parameters.parameter_ptr(prefix + "v_proj.weight");
